128		cfg, err := ops.client.Get(ctx, obj.Node, metav1.GetOptions{})
129		if err != nil {
130			if k8sErrors.IsNotFound(err) {
131				_, err = ops.client.Create(ctx,
132					&cilium_v2alpha1_api.CiliumNetworkDriverNodeConfig{
133						ObjectMeta: metav1.ObjectMeta{Name: obj.Node},
134						Spec:       *obj.Config.DeepCopy(),
135					},
136					metav1.CreateOptions{},
137				)
138			}
139			return err
140		}
141	
142		if cfg.Spec.DeepEqual(obj.Config) {
143			return nil
144		}
145	
146		newCfg := cfg.DeepCopy()
147		newCfg.Spec = *obj.Config.DeepCopy()
148	
149		_, err = ops.client.Update(ctx, newCfg, metav1.UpdateOptions{})
150		return err
