162		k8sConfigs, err := ops.client.List(ctx, metav1.ListOptions{})
163		if err != nil {
164			return err
165		}
166	
167		configs := slices.Collect(maps.Keys(maps.Collect(objects)))
168	
169		var toDelete []string
170		for _, k8sConfig := range k8sConfigs.Items {
171			if !slices.ContainsFunc(configs, func(config *driverNodeConfig) bool {
172				return config.Node == k8sConfig.Name
173			}) {
174				toDelete = append(toDelete, k8sConfig.Name)
175			}
176		}
177	
178		var errs []error
179		for _, config := range toDelete {
180			errs = append(errs, ops.client.Delete(ctx, config, metav1.DeleteOptions{}))
181		}
182		return errors.Join(errs...)
183	}
