	// First pass: validate every spec and collect the pool objects. If any
	// spec fails to parse, return the error immediately without creating any
	// pools.
	pools := make([]*cilium_v2alpha1_api.CiliumResourceIPPool, 0, len(poolMap))
	for poolName, poolSpecStr := range poolMap {
		v4PoolSpec, v6PoolSpec, err := multipool.ParsePoolSpec(poolSpecStr)
		if err != nil {
			logger.ErrorContext(ctx,
				fmt.Sprintf("Failed to parse IP pool spec in %q flag", AutoCreateCiliumResourceIPPools),
				logfields.PoolName, poolName,
				logfields.PoolSpec, poolSpecStr,
				logfields.Error, err)
			return err
		}

		pools = append(pools, &cilium_v2alpha1_api.CiliumResourceIPPool{
			ObjectMeta: metav1.ObjectMeta{
				Name: poolName,
			},
			Spec: cilium_v2alpha1_api.ResourceIPPoolSpec{
				IPv4: v4PoolSpec,
				IPv6: v6PoolSpec,
			},
		})
	}

	// Second pass: create all validated pools. Log (but do not return)
	// AlreadyExists or any other create errors and continue with the next pool.
	for _, pool := range pools {
		_, err := client.Create(ctx, pool, metav1.CreateOptions{})
		if err != nil {
			if k8sErrors.IsAlreadyExists(err) {
				// Nothing to do, we will not try to update an existing resource
